(() => {
  const sels = [
    '[data-question-other="template_edit_confirm"] .question-other-input',
    '[data-question-text="template_edit_request"] .question-text-input'
  ];
  let n = 0;
  for (const sel of sels) {
    for (const el of document.querySelectorAll(sel)) {
      if (el.value) {
        el.value = '';
        el.dispatchEvent(new Event('input', { bubbles: true }));
        n += 1;
      }
    }
  }
  return n >= 0;
})()

