(() => {
  const root = document.getElementById('preview-root');
  if (!root) return false;
  const text = root.innerText || '';
  if (!text.includes('当前告警共')) return false;
  if (text.includes('{{告警总数}}')) return false;
  return /当前告警共\s*[0-9][0-9,.]*\s*条/.test(text);
})()

